func copyBinaryOutcome(t *testing.T, group, name string, result copyTextResult, err error, output []byte) {
	t.Helper()
	want, ok := copyBinaryOutcomeRecords[group+"/"+name]
	if !ok {
		t.Fatalf("unobserved binary COPY case %s/%s; pinned discovery required", group, name)
	}
	if want.diagnostic != nil {
		copyTextDiagnostic(t, result, err, *want.diagnostic)
	} else {
		copyTextSuccess(t, result, err, want.count)
	}
	if (output != nil || len(want.output) != 0) && !bytes.Equal(output, want.output) {
		t.Errorf("COPY output=%x want=%x", output, want.output)
	}
}
